from collections import Counter
from functools import lru_cache
H,W=len(bot),len(bot[0]); target={(r,c) for r in range(H) for c in range(W) if bot[r][c]==1}
sizes=Counter({(1,1):3,(4,2):1,(2,2):2,(2,1):4,(6,2):1,(4,3):1,(3,1):1,(3,2):2})
# generate placements for each size (fixed orientations)
placements={}
for sh,n in sizes.items():
 h,w=sh; ps=[]
 for r in range(H-h+1):
  for c in range(W-w+1):
   cells=frozenset((y,x) for y in range(r,r+h) for x in range(c,c+w))
   if cells<=target: ps.append((r,c,cells))
 placements[sh]=ps
print({k:len(v) for k,v in placements.items()})

# backtracking fixed orientation, use bitsets
allcoords=sorted(target); idx={p:i for i,p in enumerate(allcoords)}
pl_bycell={p:[] for p in target}
for sh,ps in placements.items():
 for r,c,cells in ps:
  mask=sum(1<<idx[p] for p in cells)
  item=(sh,r,c,cells,mask)
  for p in cells: pl_bycell[p].append(item)
sols=[]; nodes=0

def search(used, rem, chosen):
 global nodes
 nodes+=1
 if len(used)==len(target):
  if all(v==0 for v in rem.values()): sols.append(chosen.copy())
  return len(sols)>=5
 # choose uncovered cell with minimum feasible options
 uncovered=[p for p in target if p not in used]
 best=None; optsbest=None
 for p in uncovered:
  opts=[]
  for sh,r,c,cells,mask in pl_bycell[p]:
   if rem.get(sh,0)>0 and not (mask & used): opts.append((sh,r,c,cells,mask))
  if not opts:return False
  if optsbest is None or len(opts)<len(optsbest): best=p;optsbest=opts
  if len(optsbest)==1:break
 for sh,r,c,cells,mask in optsbest:
  rem[sh]-=1
  stop=search(used|mask,rem,chosen+[(sh,r,c)])
  rem[sh]+=1
  if stop:return True
 return False
search(0,sizes.copy(),[])
print('nodes',nodes,'solutions',len(sols))
for s in sols[:2]:print(s)

